import { useEffect, useMemo, useState } from 'react';
import { useMutation, useQueries, useQuery, useQueryClient } from '@tanstack/react-query';
import { NavLink, Navigate, useOutletContext, useParams } from 'react-router-dom';
import { Activity, Building2, CheckCircle2, Database, FileCheck2, Landmark, Plus, Save, ShieldCheck, Target, Trash2, TrendingUp, UsersRound } from 'lucide-react';
import { bajomaAnnualCharge, buildingAnnualRent, gimiBudgetCashForecast, gimiBudgetProjectionIntegrity, gimiBudgetYears, hiringAnnualCost, type BfrReport, type CapexReport, type CashFlowReport, type Company, type EmployeeAnalyticAllocation, type GimiBudgetCapexCategory, type GimiBudgetDecisionKey, type GimiBudgetDriver, type GimiBudgetHiring, type GimiBudgetPlan, type GimiBudgetProjection, type GimiBudgetScenarioName, type GimiBudgetYear, type MarginAnalysisReport, type ProfitLossReport, type PublicUser } from '@equinoxe/shared';
import { api, ApiError } from '../services/api';
import { Button, Card, ErrorState, Input, LoadingState, PageHeader, Select } from '../components/ui';
import { gimiBudgetSeasonality, type GimiBudgetSeasonalityMonth } from '../services/gimi-budget-seasonality';
import './gimi-budget.css';

const scenarioLabels:Record<GimiBudgetScenarioName,string>={best:'Best case',neutral:'Neutral case',worst:'Worst case'};
const driverLabels:Record<GimiBudgetDriver,string>={growth:'Croissance du chiffre d’affaires',purchasesRate:'Achats / CA et variation des en-cours',servicesRate:'Services et biens divers / CA',payrollRate:'Rémunérations / CA',workingCapitalRate:'BFR / CA'};
const departments={fireInstallation:'Incendie — installation',fireMaintenance:'Incendie — maintenance',intrusion:'Intrusion',led:'LED',shared:'Fonctions partagées'} as const;
const validationLabels={interimBase:'Situation intermédiaire au 31/10/2026',scenarios:'Hypothèses des trois scénarios',hiring:'Plan de recrutements',indexation:'Indexations salariales',building:'Nouveau bâtiment et loyer',bajoma:'Refacturation mensuelle Bajoma'} as const;
const tabs=[['resultats','Résultats'],['kpi','KPI & hypothèses utiles'],['hypotheses','Scénarios'],['remunerations','Rémunérations'],['capex','CAPEX'],['dette','Dette & cash forecast'],['batiment','Bâtiment & flux internes'],['controles','Contrôles & sources']] as const;
const capexLabels:Record<GimiBudgetCapexCategory,string>={software:'Logiciels et développements',vehicles:'Véhicules et aménagements',it:'Informatique et mobilier',tools:'Installations et outillage',building:'Terrains et constructions',layout:'Aménagements des locaux',leasing:'Location-financement',progress:'Immobilisations en cours',other:'Autres immobilisations'};
const decisionGroups:Array<{title:string;items:Array<[GimiBudgetDecisionKey,string,string]>}>=[
  {title:'Activité commerciale',items:[['growthTaper','Trajectoire de croissance après 2027','Décider quand la croissance ralentit et à quel niveau elle converge.'],['revenueMix','Mix CA par département','Valider le poids installation, maintenance, intrusion et LED.'],['recurringRevenue','Part de revenus récurrents','Définir contrats, renouvellements et taux de rétention.'],['priceVolume','Prix versus volumes','Séparer indexation tarifaire et croissance des volumes.'],['backlog','Carnet de commandes sécurisé','Mesurer la couverture du budget 2027 déjà signée.'],['churn','Perte de contrats et clients','Fixer un taux de churn explicite.']]},
  {title:'Marge et opérations',items:[['purchaseInflation','Inflation des achats','Fixer l’inflation fournisseurs par famille.'],['pricePassThrough','Répercussion des hausses','Décider le délai et le pourcentage répercuté aux clients.'],['grossMarginDefinition','Définition de la marge brute','Confirmer si la sous-traitance est incluse avec les marchandises.'],['staffingModel','Effectifs ou ratio salarial','Choisir la source de calcul prioritaire pour éviter le double comptage.'],['productivity','CA et marge par ETP','Fixer la productivité cible par fonction et département.'],['absenceOvertime','Absentéisme, heures supplémentaires et intérim','Budgéter les coûts de capacité non planifiés.']]},
  {title:'Trésorerie et investissements',items:[['workingCapital','Délais clients et fournisseurs','Fixer DSO, DPO et acomptes clients.'],['badDebt','Créances douteuses','Fixer un taux de perte et de retard.'],['inventoryWip','Stocks et travaux en cours','Définir le niveau nécessaire à la croissance.'],['vehiclePlan','Plan véhicules','Remplacements, nouveaux véhicules et coût d’usage.'],['capexPlan','Plan CAPEX','Valider les investissements par famille et année.'],['buildingTransition','Transition du bâtiment','Double loyer, déménagement, aménagement et charges.'],['financing','Financements et remboursements','Crédits, intérêts, earn-out et échéances.'],['taxDividends','Impôts et dividendes','Fixer taux effectif, acomptes et politique de distribution.'],['seasonality','Saisonnalité CA et marge','Valider la répartition issue des mois 2025–2026.']]},
];
const money=new Intl.NumberFormat('fr-BE',{style:'currency',currency:'EUR',maximumFractionDigits:0});
const preciseMoney=new Intl.NumberFormat('fr-BE',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2});
const percent=(value:number|null)=>value===null?'À valider':`${(value*100).toLocaleString('fr-BE',{maximumFractionDigits:2})} %`;

export function GimiBudget(){
  const {budgetTab='resultats'}=useParams(),{me,current}=useOutletContext<{me:PublicUser;current:Company}>(),editable=me.role==='admin',queryClient=useQueryClient();
  const query=useQuery({queryKey:['gimi-budget-plan',current.id],queryFn:()=>api.gimiBudgetPlan(current.id),enabled:current.slug==='gimi'});
  const projection=useQuery({queryKey:['gimi-budget-projection',current.id],queryFn:()=>api.gimiBudgetProjection(current.id),enabled:current.slug==='gimi'});
  const monthly=useQueries({queries:[2025,2026].map(year=>({queryKey:['profit-loss-months',current.id,year,'budget-seasonality'],queryFn:()=>api.profitLossMonths(current.id,year),enabled:current.slug==='gimi'&&['resultats','kpi','controles'].includes(budgetTab),retry:1}))});
  const profit=useQuery({queryKey:['profit-loss-extrapolated',current.id,'budget-kpi'],queryFn:()=>api.profitLossExtrapolated(current.id),enabled:current.slug==='gimi'&&['kpi','controles'].includes(budgetTab),retry:1});
  const margin=useQuery({queryKey:['margin-analysis',current.id,'budget-kpi'],queryFn:()=>api.marginAnalysis(current.id),enabled:current.slug==='gimi'&&['kpi','controles'].includes(budgetTab),retry:1});
  const bfr=useQuery({queryKey:['bfr',current.id,'budget-kpi'],queryFn:()=>api.bfr(current.id),enabled:current.slug==='gimi'&&['kpi','dette','controles'].includes(budgetTab),retry:1});
  const capex=useQuery({queryKey:['gimi-capex',current.id,'budget'],queryFn:()=>api.capex(current.id),enabled:current.slug==='gimi'&&['kpi','capex','controles'].includes(budgetTab),retry:1});
  const cashFlow=useQuery({queryKey:['gimi-cash-flow',current.id,'budget'],queryFn:()=>api.cashFlow(current.id),enabled:current.slug==='gimi'&&['dette','controles'].includes(budgetTab),retry:1});
  const employees=useQuery({queryKey:['employee-analytic-allocations',current.id],queryFn:()=>api.employeeAnalyticAllocations(current.id),enabled:current.slug==='gimi'&&editable});
  const [draft,setDraft]=useState<GimiBudgetPlan|null>(null);
  useEffect(()=>{if(query.data)setDraft(query.data);},[query.data]);
  const save=useMutation({mutationFn:(value:GimiBudgetPlan)=>api.saveGimiBudgetPlan(current.id,withoutServerFields(value)),onSuccess:value=>{setDraft(value);queryClient.invalidateQueries({queryKey:['gimi-budget-projection',current.id]});}});
  if(current.slug!=='gimi')return <Navigate to="/budget/gimi/2027/resultats" replace/>;
  if(query.isLoading||!draft)return <LoadingState/>;
  if(query.error)return <ErrorState message="Impossible de charger le budget Gimi."/>;
  const tab=tabs.some(([key])=>key===budgetTab)?budgetTab:'resultats';
  const seasonality=gimiBudgetSeasonality(monthly[0].data,monthly[1].data,projection.data);
  return <div className="gimi-budget-page">
    <PageHeader title="Budget Gimi · 2027–2036"><div className="budget-header-actions"><span>Version de travail · priorité 2027</span>{editable&&<Button onClick={()=>save.mutate(draft)} disabled={save.isPending}><Save size={16}/>{save.isPending?'Enregistrement…':'Enregistrer'}</Button>}</div></PageHeader>
    <nav className="budget-tabs" aria-label="Sections du budget">{tabs.map(([key,label])=><NavLink key={key} className={tab===key?'active':''} to={`/budget/gimi/2027/${key}`}>{label}</NavLink>)}</nav>
    {save.error&&<div className="form-error" role="alert">{save.error instanceof ApiError&&save.error.status===409?'Le budget a changé dans une autre session. Rechargez la page avant de recommencer.':'Le budget n’a pas pu être enregistré.'}</div>}
    {save.isSuccess&&<div className="form-success" role="status">Budget enregistré dans la base partagée.</div>}
    {tab==='resultats'?<Results projection={projection.data} seasonality={seasonality} seasonalityLoading={monthly.some(item=>item.isLoading)} loading={projection.isLoading} error={projection.isError}/>:tab==='kpi'?<KpiAndDecisions plan={draft} profit={profit.data} margin={margin.data} bfr={bfr.data} capex={capex.data} seasonality={seasonality} sourceUnavailable={[profit,margin,bfr,capex].some(item=>item.isError)} editable={editable} onChange={setDraft}/>:tab==='hypotheses'?<Assumptions plan={draft} editable={editable} onChange={setDraft}/>:tab==='remunerations'?<Remuneration plan={draft} employees={employees.data??[]} editable={editable} onChange={setDraft}/>:tab==='capex'?<CapexBudget plan={draft} report={capex.data} unavailable={capex.isError} editable={editable} onChange={setDraft}/>:tab==='dette'?<DebtAndCashForecast plan={draft} projection={projection.data} bfr={bfr.data} cashFlow={cashFlow.data} editable={editable} onChange={setDraft}/>:tab==='controles'?<BudgetControls plan={draft} projection={projection.data} seasonality={seasonality} profit={profit.data} margin={margin.data} bfr={bfr.data} capex={capex.data} cashFlow={cashFlow.data} loading={[projection,profit,margin,bfr,capex,cashFlow,...monthly].some(item=>item.isLoading)}/>:<BuildingAndManagement plan={draft} editable={editable} onChange={setDraft}/>}
  </div>;
}

const withoutServerFields=({companyId:_,updatedAt:__,updatedByUserId:___,...value}:GimiBudgetPlan)=>value;

function Results({projection,seasonality,seasonalityLoading,loading,error}:{projection?:GimiBudgetProjection;seasonality:GimiBudgetSeasonalityMonth[]|null;seasonalityLoading:boolean;loading:boolean;error:boolean}){
  if(loading)return <LoadingState/>;if(error||!projection)return <ErrorState message="Impossible de calculer le premier résultat budgétaire."/>;
  const ebitda=projection.lines.find(line=>line.key==='ebitda'),net=projection.lines.find(line=>line.key==='netResult'),revenue=projection.lines.find(line=>line.key==='revenue'),year='2027';
  const kAmount=(value:number)=>Math.round(value/1000).toLocaleString('fr-BE'),display=(line:GimiBudgetProjection['lines'][number],value:number)=>line.kind==='percentage'?`${(value*100).toLocaleString('fr-BE',{minimumFractionDigits:1,maximumFractionDigits:1})} %`:kAmount(value);
  return <>
    <Card className="budget-results-hero"><TrendingUp/><div><p className="eyebrow">Premier résultat · scénario {scenarioLabels[projection.scenario]}</p><h2>Budget consolidé 2027–2036</h2><p>Projection initiale construite à partir de la base 2026 et des hypothèses enregistrées. Les flux confidentiels sont intégrés dans les agrégats, sans détail dans le navigateur.</p><p className={`budget-source-note ${projection.source==='interimAnnualized'?'verified':'provisional'}`}>{projection.sourceNote}</p></div><div className="budget-result-kpis"><span>CA 2027 · kEUR<strong>{revenue?kAmount(revenue.values[year]):'—'}</strong></span><span>EBITDA 2027 · kEUR<strong>{ebitda?kAmount(ebitda.values[year]):'—'}</strong></span><span>Résultat net 2027 · kEUR<strong>{net?kAmount(net.values[year]):'—'}</strong></span></div></Card>
    <Card className="budget-results-card"><div className="card-title-row"><div><p className="eyebrow">Compte de résultat prévisionnel</p><h2>Vue sur dix ans</h2><p>Montants arrondis en milliers d’euros. Enregistrez les hypothèses pour recalculer cette synthèse.</p></div><span className="budget-base-date">{projection.source==='interimAnnualized'?'Base annualisée':'Arrêté cible'} · {new Date(`${projection.baseDate}T12:00:00`).toLocaleDateString('fr-BE')}</span></div><div className="budget-table-wrap"><table className="budget-result-table"><thead><tr><th>Rubrique <small>· kEUR</small></th>{projection.years.map(item=><th className={item===2027?'focus-year':''} key={item}>{item}</th>)}</tr></thead><tbody>{projection.lines.map(line=><tr className={`${line.kind==='percentage'?'ratio-row':''} ${line.emphasis?`result-${line.emphasis}`:''}`} key={line.key}><th>{line.label}</th>{projection.years.map(item=><td className={item===2027?'focus-year':''} key={item}>{display(line,line.values[String(item)])}</td>)}</tr>)}</tbody></table></div><p className="report-note">Cette première vue ne constitue pas encore un plan de trésorerie : le BFR, les investissements et les financements devront être ajoutés après validation des hypothèses opérationnelles avec Basile.</p></Card>
    <Card className="budget-seasonality-card"><div className="card-title-row"><div><p className="eyebrow">Budget mensuel 2027</p><h2>Saisonnalité du chiffre d’affaires et de la marge</h2><p>Répartition issue de 2025 sur douze mois, affinée par les mois disponibles de 2026.</p></div></div>{seasonalityLoading?<LoadingState/>:seasonality?<div className="budget-table-wrap"><table className="seasonality-table"><thead><tr><th>Rubrique <small>· kEUR</small></th>{seasonality.map(row=><th key={row.month}>{new Date(`${row.month}-15T12:00:00`).toLocaleDateString('fr-BE',{month:'short'})}</th>)}</tr></thead><tbody><tr><th>CA</th>{seasonality.map(row=><td key={row.month}>{kAmount(row.revenue)}</td>)}</tr><tr className="ratio-row"><th>Part annuelle</th>{seasonality.map(row=><td key={row.month}>{(row.revenueShare*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} %</td>)}</tr><tr><th>Marge brute</th>{seasonality.map(row=><td key={row.month}>{kAmount(row.grossMargin)}</td>)}</tr><tr className="ratio-row"><th>Taux de marge</th>{seasonality.map(row=><td key={row.month}>{row.grossMarginRate===null?'—':`${(row.grossMarginRate*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} %`}</td>)}</tr></tbody></table></div>:<p className="budget-data-unavailable">Saisonnalité indisponible dans cet environnement : les rapports mensuels Odoo 2025 et 2026 sont nécessaires.</p>}</Card>
  </>;
}

function KpiAndDecisions({plan,profit,margin,bfr,capex,seasonality,sourceUnavailable,editable,onChange}:{plan:GimiBudgetPlan;profit?:ProfitLossReport;margin?:MarginAnalysisReport;bfr?:BfrReport;capex?:CapexReport;seasonality:GimiBudgetSeasonalityMonth[]|null;sourceUnavailable:boolean;editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  const latestYear=profit?.years[profit.years.length-1],yearKey=latestYear?String(latestYear):null;
  const findLine=(terms:string[])=>profit?.lines.find(line=>terms.some(term=>`${line.key} ${line.label}`.toLocaleLowerCase('fr-BE').includes(term)));
  const revenue=findLine(['chiffre d’affaires','chiffre d\'affaires','revenue']),grossMargin=findLine(['marge brute','gross margin']),ebitda=findLine(['ebitda']);
  const revenueValue=yearKey&&revenue?revenue.values[yearKey]:null,grossMarginValue=yearKey&&grossMargin?grossMargin.values[yearKey]:null,ebitdaValue=yearKey&&ebitda?ebitda.values[yearKey]:null;
  const latestCapex=capex?.periods[capex.periods.length-1],bfrValue=yearKey&&bfr?bfr.total[yearKey]:null;
  const peakMonth=seasonality?.reduce((best,row)=>row.revenueShare>best.revenueShare?row:best),lowMonth=seasonality?.reduce((best,row)=>row.revenueShare<best.revenueShare?row:best);
  const kpi=(label:string,value:number|null|undefined,detail:string,ratio=false)=><div className="budget-kpi-card"><span>{label}</span><strong>{value===null||value===undefined?'—':ratio?`${(value*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} %`:money.format(value)}</strong><small>{detail}</small></div>;
  const marginBlock=margin?.blocks.find(block=>block.key==='margin'),marginYear=margin?.years[margin.years.length-1];
  return <>
    <Card className="budget-intro"><Activity/><div><p className="eyebrow">Pilotage du budget</p><h2>KPI de référence et décisions à prendre</h2><p>Les KPI sont lus dans le reporting financier Odoo de Gimi. Les cases servent à suivre les hypothèses réellement tranchées avec Basile.</p></div></Card>
    {sourceUnavailable&&<div className="budget-data-unavailable" role="status">Une partie des données Odoo n’est pas accessible dans cet environnement. Les valeurs concernées restent vides ; elles ne sont pas remplacées par des estimations.</div>}
    <div className="budget-kpi-grid">
      {kpi(`Chiffre d’affaires ${latestYear??''}`,revenueValue,'Compte de résultat extrapolé')}
      {kpi('Taux de marge brute',revenueValue&&grossMarginValue!==null&&grossMarginValue!==undefined?grossMarginValue/revenueValue:null,`Réalisé / extrapolé ${latestYear??'indisponible'}`,true)}
      {kpi('Marge EBITDA',revenueValue&&ebitdaValue!==null&&ebitdaValue!==undefined?ebitdaValue/revenueValue:null,`Réalisé / extrapolé ${latestYear??'indisponible'}`,true)}
      {kpi('BFR / CA',revenueValue&&bfrValue!==null&&bfrValue!==undefined?bfrValue/revenueValue:null,`BFR d’exploitation ${latestYear??'indisponible'}`,true)}
      {kpi('Acquisitions CAPEX',latestCapex?.acquisitions,latestCapex?`Exercice ${latestCapex.year}`:'Reporting CAPEX indisponible')}
      {kpi('Valeur nette immobilisée',latestCapex?.closingNet,latestCapex?`Clôture ${latestCapex.year}`:'Reporting CAPEX indisponible')}
    </div>
    {seasonality&&peakMonth&&lowMonth&&<Card className="budget-seasonality-summary"><Target/><div><p className="eyebrow">Saisonnalité proposée</p><h2>Pic en {monthName(peakMonth.month)}, creux en {monthName(lowMonth.month)}</h2><p>{monthName(peakMonth.month)} représente {(peakMonth.revenueShare*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} % du CA annuel proposé, contre {(lowMonth.revenueShare*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} % en {monthName(lowMonth.month)}. Cette clé reste à valider avant de mensualiser le budget.</p></div></Card>}
    {marginBlock&&marginYear&&<Card><div className="card-title-row"><div><p className="eyebrow">Analyse de marge</p><h2>Repères disponibles par département</h2><p>Dernière année disponible dans le reporting : {marginYear}.</p></div></div><div className="budget-table-wrap"><table className="budget-compact-table"><thead><tr><th>Département</th><th>Marge</th><th>Part du total</th></tr></thead><tbody>{marginBlock.rows.map(row=>{const value=row.values[String(marginYear)]??0,total=marginBlock.totals[String(marginYear)]??0;return <tr key={row.key}><th>{row.label}</th><td>{money.format(value)}</td><td>{total?`${(value/total*100).toLocaleString('fr-BE',{maximumFractionDigits:1})} %`:'—'}</td></tr>})}</tbody></table></div></Card>}
    {decisionGroups.map(group=><Card className="decision-section" key={group.title}><div className="card-title-row"><div><p className="eyebrow">Hypothèses utiles</p><h2>{group.title}</h2></div><span>{group.items.filter(([key])=>plan.decisions[key]).length} / {group.items.length} validées</span></div><div className="decision-grid">{group.items.map(([key,label,description])=><label className={plan.decisions[key]?'decision-item checked':'decision-item'} key={key}><input type="checkbox" checked={plan.decisions[key]} disabled={!editable} onChange={event=>onChange({...plan,decisions:{...plan.decisions,[key]:event.target.checked}})}/><CheckCircle2 size={18}/><span><strong>{label}</strong><small>{description}</small></span></label>)}</div></Card>)}
  </>;
}

function CapexBudget({plan,report,unavailable,editable,onChange}:{plan:GimiBudgetPlan;report?:CapexReport;unavailable:boolean;editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  const latest=report?.periods[report.periods.length-1];
  const update=(category:GimiBudgetCapexCategory,year:GimiBudgetYear,value:number|null)=>onChange({...plan,capexBudget:{...plan.capexBudget,[category]:{...plan.capexBudget[category],[year]:value}}});
  const total=(year:GimiBudgetYear)=>Object.keys(capexLabels).reduce((sum,key)=>sum+(plan.capexBudget[key as GimiBudgetCapexCategory][year]??0),0);
  const hasValue=(year:GimiBudgetYear)=>Object.keys(capexLabels).some(key=>plan.capexBudget[key as GimiBudgetCapexCategory][year]!==null);
  return <>
    <Card className="budget-intro"><Target/><div><p className="eyebrow">Plan d’investissement</p><h2>CAPEX 2027–2036</h2><p>Les familles reprennent le reporting Investissements – CAPEX. Les montants futurs restent à compléter et à valider ; aucune extrapolation automatique n’est appliquée.</p></div></Card>
    {unavailable&&<div className="budget-data-unavailable" role="status">Le reporting CAPEX Odoo n’est pas accessible dans cet environnement. Le plan futur peut néanmoins être complété et enregistré.</div>}
    {latest&&<><div className="budget-kpi-grid capex-kpis"><div className="budget-kpi-card"><span>Acquisitions {latest.year}</span><strong>{money.format(latest.acquisitions)}</strong><small>Écritures Odoo</small></div><div className="budget-kpi-card"><span>Amortissements {latest.year}</span><strong>{money.format(latest.amortization)}</strong><small>Reporting CAPEX</small></div><div className="budget-kpi-card"><span>Valeur nette de clôture</span><strong>{money.format(latest.closingNet)}</strong><small>Au {new Date(`${latest.through}T12:00:00`).toLocaleDateString('fr-BE')}</small></div></div><Card><div className="card-title-row"><div><p className="eyebrow">Référence historique</p><h2>Investissements {latest.year} par famille</h2></div></div><div className="budget-table-wrap"><table className="budget-compact-table"><thead><tr><th>Famille</th><th>Acquisitions</th><th>Valeur nette</th><th>Amortissements</th></tr></thead><tbody>{latest.categories.map(category=><tr key={category.key}><th>{category.label}</th><td>{money.format(category.acquisitions)}</td><td>{money.format(category.net)}</td><td>{money.format(category.amortization)}</td></tr>)}</tbody></table></div></Card></>}
    <Card className="capex-plan-card"><div className="card-title-row"><div><p className="eyebrow">Hypothèses à compléter</p><h2>Budget d’investissement par année</h2><p>Montants hors TVA en euros. La priorité de validation porte sur 2027.</p></div></div><div className="budget-table-wrap"><table className="capex-budget-table"><thead><tr><th>Famille</th>{gimiBudgetYears.map(year=><th className={year===2027?'focus-year':''} key={year}>{year}</th>)}</tr></thead><tbody>{(Object.keys(capexLabels) as GimiBudgetCapexCategory[]).map(category=><tr key={category}><th>{capexLabels[category]}</th>{gimiBudgetYears.map(year=><td className={year===2027?'focus-year':''} key={year}><Input type="number" min="0" step="1000" value={plan.capexBudget[category][year]??''} placeholder="—" disabled={!editable} onChange={event=>update(category,year,event.target.value===''?null:Math.max(0,Number(event.target.value)||0))}/></td>)}</tr>)}<tr className="capex-total-row"><th>Total CAPEX</th>{gimiBudgetYears.map(year=><td className={year===2027?'focus-year':''} key={year}>{hasValue(year)?money.format(total(year)):'—'}</td>)}</tr></tbody></table></div><p className="report-note">À relier ensuite au plan de trésorerie : calendrier de paiement, TVA, financement, cessions et amortissements ne sont pas encore déduits de cette grille.</p></Card>
  </>;
}

function DebtAndCashForecast({plan,projection,bfr,cashFlow,editable,onChange}:{plan:GimiBudgetPlan;projection?:GimiBudgetProjection;bfr?:BfrReport;cashFlow?:CashFlowReport;editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  if(!projection)return <LoadingState/>;
  const actualBfr=bfr?.total['2026']??null,forecast=gimiBudgetCashForecast(plan,projection,actualBfr),first=forecast[0],scenario=plan.selectedScenario;
  const updateDebt=(key:'cbc'|'mbp1'|'mbp2'|'mbpGroupReference',year:GimiBudgetYear,value:number|null)=>onChange({...plan,debtForecast:{...plan.debtForecast,[key]:{...plan.debtForecast[key],[year]:value}}});
  const updateBfr=(year:GimiBudgetYear,value:number|null)=>onChange({...plan,scenarios:{...plan.scenarios,[scenario]:{...plan.scenarios[scenario],values:{...plan.scenarios[scenario].values,workingCapitalRate:{...plan.scenarios[scenario].values.workingCapitalRate,[year]:value}}}}});
  const amount=(value:number|null,negative=false)=>value===null?'—':money.format(negative&&value!==0?-value:value),ratio=(value:number|null)=>value===null?'—':`${value.toLocaleString('fr-BE',{maximumFractionDigits:2})}×`;
  const historicalCash=cashFlow?.closingCash?.['2026']??null,through=cashFlow?.through;
  const debtRows:Array<{key:'cbc'|'mbpGroupReference'|'mbp1'|'mbp2';label:string;note:string;disabled:boolean}>=[
    {key:'cbc',label:'Rachat 1 · CBC',note:'Référence source : 330 k€ par an jusqu’en 2029.',disabled:false},
    {key:'mbpGroupReference',label:'MBP Group · référence non ventilée',note:'Référence source : 149 k€ par an jusqu’en 2031.',disabled:!plan.debtForecast.useMbpGroupReference},
    {key:'mbp1',label:'MBP · crédit 1',note:'Échéancier à compléter.',disabled:plan.debtForecast.useMbpGroupReference},
    {key:'mbp2',label:'MBP · crédit 2',note:'Échéancier à compléter.',disabled:plan.debtForecast.useMbpGroupReference},
  ];
  const fullBeforeDebt=(row:typeof first)=>row.workingCapitalImpact===null||row.capex===null?null:row.operatingCashFlow+row.workingCapitalImpact-row.capex;
  const firstBeforeDebt=fullBeforeDebt(first),maxCashAfterDebt=Math.max(...forecast.map(row=>Math.abs(row.cashAfterDebt??0)),1);
  return <>
    <Card className="budget-intro"><Landmark/><div><p className="eyebrow">Financement et liquidité</p><h2>Dette et cash forecast 2027–2036</h2><p>Le tableau part du résultat net, réintègre les amortissements, puis déduit le BFR, le CAPEX et les remboursements de capital. Les intérêts restent dans le résultat et ne sont pas déduits une seconde fois.</p></div></Card>
    <div className="budget-kpi-grid"><div className="budget-kpi-card"><span>Cash-flow des résultats 2027</span><strong>{amount(first.operatingCashFlow)}</strong><small>Résultat net + amortissements</small></div><div className="budget-kpi-card"><span>Remboursements 2027</span><strong>{amount(first.totalDebtRepayment,true)}</strong><small>CBC + MBP</small></div><div className="budget-kpi-card"><span>Cash après dette 2027</span><strong>{amount(first.cashAfterDebt)}</strong><small>Hors BFR et CAPEX</small></div><div className="budget-kpi-card"><span>Cash-flow libre complet 2027</span><strong>{amount(first.freeCashFlow)}</strong><small>{first.freeCashFlow===null?'BFR ou CAPEX à compléter':'Après BFR, CAPEX et dette'}</small></div><div className="budget-kpi-card"><span>Couverture du capital 2027</span><strong>{ratio(first.capitalCoverage)}</strong><small>Cash des résultats / remboursements</small></div><div className="budget-kpi-card"><span>Trésorerie Odoo de référence</span><strong>{amount(historicalCash)}</strong><small>{through?`Au ${new Date(`${through}T12:00:00`).toLocaleDateString('fr-BE')}`:'Source Odoo indisponible'}</small></div></div>
    <Card className="cash-summary-card"><div className="cash-summary-heading"><div><p className="eyebrow">Résumé financier</p><h2>De la performance au cash disponible</h2><p>Lecture rapide du scénario {scenarioLabels[scenario].toLowerCase()}, avec 2027 comme année prioritaire.</p></div><span>2027 prioritaire</span></div><div className="cash-bridge" aria-label="Pont de trésorerie 2027"><div className="cash-bridge-step positive"><small>Cash des résultats</small><strong>{amount(first.operatingCashFlow)}</strong><span>Résultat net + amortissements</span></div><div className="cash-bridge-operator">+</div><div className={`cash-bridge-step ${first.workingCapitalImpact===null?'missing':first.workingCapitalImpact>=0?'positive':'negative'}`}><small>Variation du BFR</small><strong>{first.workingCapitalImpact===null?'À compléter':amount(first.workingCapitalImpact)}</strong><span>{first.workingCapitalImpact===null?'Taux BFR manquant':'Impact sur la trésorerie'}</span></div><div className="cash-bridge-operator">−</div><div className={`cash-bridge-step ${first.capex===null?'missing':'negative'}`}><small>CAPEX</small><strong>{first.capex===null?'À compléter':amount(first.capex)}</strong><span>Investissements décaissés</span></div><div className="cash-bridge-operator">−</div><div className="cash-bridge-step negative"><small>Capital remboursé</small><strong>{amount(first.totalDebtRepayment)}</strong><span>CBC + MBP</span></div><div className="cash-bridge-operator equals">=</div><div className={`cash-bridge-step result ${first.freeCashFlow===null?'missing':first.freeCashFlow>=0?'positive':'negative'}`}><small>Cash-flow libre</small><strong>{first.freeCashFlow===null?'À compléter':amount(first.freeCashFlow)}</strong><span>{first.freeCashFlow===null?'BFR et CAPEX requis':'Après service de la dette'}</span></div></div><div className="cash-summary-table-wrap"><table className="cash-summary-table"><thead><tr><th>Trajectoire synthétique</th>{forecast.map(row=><th className={row.year===2027?'focus-year':''} key={row.year}>{row.year}</th>)}</tr></thead><tbody><tr><th>Cash généré par les résultats</th>{forecast.map(row=><td key={row.year}>{amount(row.operatingCashFlow)}</td>)}</tr><tr><th>Cash libre avant dette</th>{forecast.map(row=><td key={row.year}>{amount(fullBeforeDebt(row))}</td>)}</tr><tr><th>Remboursements de capital</th>{forecast.map(row=><td className="outflow" key={row.year}>{amount(row.totalDebtRepayment,true)}</td>)}</tr><tr className="cash-summary-highlight"><th>Cash après dette · hors BFR et CAPEX</th>{forecast.map(row=><td key={row.year}><strong>{amount(row.cashAfterDebt)}</strong><span className="cash-mini-bar"><i style={{width:`${Math.abs(row.cashAfterDebt??0)/maxCashAfterDebt*100}%`}}/></span></td>)}</tr><tr className="cash-summary-result"><th>Cash-flow libre complet</th>{forecast.map(row=><td key={row.year}>{amount(row.freeCashFlow)}</td>)}</tr></tbody></table></div><p className="cash-summary-note">Le cash après dette reste lisible immédiatement. Le cash-flow libre complet ne sera affiché qu’après validation du BFR et du plan CAPEX.</p></Card>
    <Card className="debt-assumptions-card"><div className="card-title-row"><div><p className="eyebrow">Échéanciers à confirmer</p><h2>Remboursements de capital</h2><p>Montants positifs saisis en euros ; ils sont présentés comme sorties de trésorerie dans le cash forecast.</p></div></div><label className="budget-switch debt-reference-switch"><input type="checkbox" checked={plan.debtForecast.useMbpGroupReference} disabled={!editable} onChange={event=>onChange({...plan,debtForecast:{...plan.debtForecast,useMbpGroupReference:event.target.checked}})}/><span>Utiliser la référence agrégée MBP Group tant que le split des deux crédits n’est pas confirmé</span></label><div className="budget-table-wrap"><table className="debt-budget-table"><thead><tr><th>Crédit</th>{gimiBudgetYears.map(year=><th className={year===2027?'focus-year':''} key={year}>{year}</th>)}</tr></thead><tbody>{debtRows.map(row=><tr className={row.disabled?'muted-row':''} key={row.key}><th>{row.label}<small>{row.note}</small></th>{gimiBudgetYears.map(year=><td className={year===2027?'focus-year':''} key={year}><Input type="number" min="0" step="1000" value={plan.debtForecast[row.key][year]??''} placeholder="—" disabled={!editable||row.disabled} onChange={event=>updateDebt(row.key,year,event.target.value===''?null:Math.max(0,Number(event.target.value)||0))}/></td>)}</tr>)}<tr className="capex-total-row"><th>Total utilisé dans le forecast</th>{forecast.map(row=><td className={row.year===2027?'focus-year':''} key={row.year}>{amount(row.totalDebtRepayment,true)}</td>)}</tr></tbody></table></div>{plan.debtForecast.useMbpGroupReference&&<p className="budget-data-unavailable">Le fichier source ne sépare pas les deux crédits MBP. Le forecast utilise provisoirement la ligne MBP Group de 149 k€ ; désactivez la référence après avoir complété les deux échéanciers.</p>}</Card>
    <Card className="debt-cash-inputs"><div><p className="eyebrow">Hypothèses de trésorerie</p><h2>BFR et trésorerie d’ouverture</h2><p>Le scénario actif est {scenarioLabels[scenario]}. Les taux BFR saisis ici mettent à jour ce même scénario.</p></div><label>Trésorerie au 1er janvier 2027<Input type="number" step="1000" value={plan.debtForecast.openingCash2027??''} placeholder="À compléter" disabled={!editable} onChange={event=>onChange({...plan,debtForecast:{...plan.debtForecast,openingCash2027:event.target.value===''?null:Number(event.target.value)}})}/>{historicalCash!==null&&<small>Référence Odoo au {through?new Date(`${through}T12:00:00`).toLocaleDateString('fr-BE'):'dernier arrêté'} : {money.format(historicalCash)}</small>}</label><div className="budget-table-wrap"><table className="bfr-rate-table"><thead><tr><th>BFR / CA</th>{gimiBudgetYears.map(year=><th key={year}>{year}</th>)}</tr></thead><tbody><tr><th>Taux du scénario</th>{gimiBudgetYears.map(year=><td key={year}><RateInput value={plan.scenarios[scenario].values.workingCapitalRate[year]} disabled={!editable} onChange={value=>updateBfr(year,value)}/></td>)}</tr></tbody></table></div></Card>
    <Card className="cash-forecast-card"><div className="card-title-row"><div><p className="eyebrow">Prévision de trésorerie</p><h2>Cash-flow libre et trésorerie de clôture</h2><p>Le cash-flow complet reste indisponible tant que toutes les catégories CAPEX, le BFR et la trésorerie d’ouverture ne sont pas renseignés.</p></div></div><div className="budget-table-wrap"><table className="cash-forecast-table"><thead><tr><th>Rubrique</th>{forecast.map(row=><th className={row.year===2027?'focus-year':''} key={row.year}>{row.year}</th>)}</tr></thead><tbody><tr><th>Résultat net</th>{forecast.map(row=><td key={row.year}>{amount(row.netResult)}</td>)}</tr><tr><th>+ Amortissements</th>{forecast.map(row=><td key={row.year}>{amount(row.depreciationAddBack)}</td>)}</tr><tr className="cash-subtotal"><th>Cash-flow généré par les résultats</th>{forecast.map(row=><td key={row.year}>{amount(row.operatingCashFlow)}</td>)}</tr><tr><th>− / + Variation du BFR</th>{forecast.map(row=><td key={row.year}>{amount(row.workingCapitalImpact)}</td>)}</tr><tr><th>− CAPEX</th>{forecast.map(row=><td key={row.year}>{amount(row.capex,true)}</td>)}</tr><tr className="cash-subtotal"><th>Cash-flow libre avant dette</th>{forecast.map(row=><td key={row.year}>{amount(fullBeforeDebt(row))}</td>)}</tr><tr><th>− Rachat 1 · CBC</th>{forecast.map(row=><td key={row.year}>{amount(row.cbcRepayment,true)}</td>)}</tr><tr><th>− MBP</th>{forecast.map(row=><td key={row.year}>{amount(row.mbpRepayment,true)}</td>)}</tr><tr className="cash-secondary-result"><th>Cash après dette · hors BFR et CAPEX</th>{forecast.map(row=><td key={row.year}>{amount(row.cashAfterDebt)}</td>)}</tr><tr className="cash-primary-result"><th>Cash-flow libre complet</th>{forecast.map(row=><td key={row.year}>{amount(row.freeCashFlow)}</td>)}</tr><tr><th>Trésorerie d’ouverture</th>{forecast.map(row=><td key={row.year}>{amount(row.openingCash)}</td>)}</tr><tr className="cash-closing"><th>Trésorerie de clôture</th>{forecast.map(row=><td key={row.year}>{amount(row.closingCash)}</td>)}</tr></tbody></table></div><p className="report-note">Les remboursements saisis doivent représenter le capital uniquement. Le loyer du bâtiment et les flux Bajoma sont déjà intégrés dans le compte de résultat projeté. <NavLink to="/budget/gimi/2027/capex">Compléter le plan CAPEX</NavLink>.</p></Card>
  </>;
}

type BudgetControlStatus='ok'|'warning'|'missing';
const controlStatusLabel:Record<BudgetControlStatus,string>={ok:'Contrôle réussi',warning:'À confirmer',missing:'Indisponible'};

function BudgetControls({plan,projection,seasonality,profit,margin,bfr,capex,cashFlow,loading}:{plan:GimiBudgetPlan;projection?:GimiBudgetProjection;seasonality:GimiBudgetSeasonalityMonth[]|null;profit?:ProfitLossReport;margin?:MarginAnalysisReport;bfr?:BfrReport;capex?:CapexReport;cashFlow?:CashFlowReport;loading:boolean}){
  if(!projection)return loading?<LoadingState/>:<ErrorState message="La projection budgétaire nécessaire aux contrôles est indisponible."/>;
  const integrity=gimiBudgetProjectionIntegrity(projection),scenario=plan.scenarios[plan.selectedScenario].values;
  const completeValues=(values:Record<string,number|null>)=>gimiBudgetYears.every(year=>values[year]!==null);
  const bfrComplete=completeValues(scenario.workingCapitalRate),capexComplete=Object.values(plan.capexBudget).every(completeValues);
  const debtComplete=completeValues(plan.debtForecast.cbc)&&(plan.debtForecast.useMbpGroupReference?completeValues(plan.debtForecast.mbpGroupReference):completeValues(plan.debtForecast.mbp1)&&completeValues(plan.debtForecast.mbp2));
  const validationCount=Object.values(plan.validation).filter(Boolean).length,validationTotal=Object.keys(plan.validation).length;
  const checks:Array<{title:string;detail:string;status:BudgetControlStatus;link?:string}>=[
    {title:'Cohérence arithmétique du compte de résultat',detail:integrity.ok?`${integrity.checkedYears.length} années contrôlées : marge, EBITDA, résultat et cash opérationnel se réconcilient.`:`${integrity.failures.length} incohérence(s) détectée(s) : ${integrity.failures.slice(0,2).join(', ')}.`,status:integrity.ok?'ok':'missing'},
    {title:'Base de départ 2026',detail:projection.source==='interimAnnualized'?`Situation Odoo arrêtée au ${new Date(`${projection.baseDate}T12:00:00`).toLocaleDateString('fr-BE')} et annualisée.`:'Référence du fichier Budget 2026 utilisée provisoirement : la base Odoo n’a pas alimenté cette projection.',status:projection.source==='interimAnnualized'?'ok':'warning',link:'/budget/gimi/2027/hypotheses'},
    {title:'Scénario et horizon',detail:`${scenarioLabels[plan.selectedScenario]} appliqué de 2027 à 2036 ; 2026 reste l’année de référence.`,status:projection.scenario===plan.selectedScenario&&projection.years.join(',')==='2026,2027,2028,2029,2030,2031,2032,2033,2034,2035,2036'?'ok':'missing'},
    {title:'BFR du cash forecast',detail:bfrComplete?'Un taux BFR / CA est renseigné pour chaque année.':'Au moins un taux BFR / CA manque : le cash-flow libre complet reste indisponible.',status:bfrComplete?'ok':'warning',link:'/budget/gimi/2027/dette'},
    {title:'Plan CAPEX',detail:capexComplete?'Toutes les familles CAPEX sont renseignées de 2027 à 2036.':'Des catégories ou années CAPEX restent vides ; elles ne sont pas remplacées par zéro.',status:capexComplete?'ok':'warning',link:'/budget/gimi/2027/capex'},
    {title:'Échéanciers de dette',detail:!debtComplete?'Un échéancier CBC ou MBP est incomplet.':plan.debtForecast.useMbpGroupReference?'CBC est renseigné ; MBP utilise encore la référence agrégée non ventilée.':'CBC et les deux crédits MBP sont renseignés séparément.',status:!debtComplete?'missing':plan.debtForecast.useMbpGroupReference?'warning':'ok',link:'/budget/gimi/2027/dette'},
    {title:'Trésorerie d’ouverture 2027',detail:plan.debtForecast.openingCash2027===null?'Le solde au 1er janvier 2027 doit encore être confirmé. Le solde Odoo au 31 octobre n’est qu’un repère.':`Solde saisi : ${money.format(plan.debtForecast.openingCash2027)}.`,status:plan.debtForecast.openingCash2027===null?'warning':'ok',link:'/budget/gimi/2027/dette'},
    {title:'Indexations salariales',detail:plan.salaryIndexation.cp200!==null&&plan.salaryIndexation.cp14901!==null?'CP 200 et CP 149.01 sont renseignées.':'L’indexation CP 149.01 ou CP 200 reste à confirmer.',status:plan.salaryIndexation.cp200!==null&&plan.salaryIndexation.cp14901!==null?'ok':'warning',link:'/budget/gimi/2027/remunerations'},
    {title:'Validation métier des hypothèses',detail:`${validationCount} hypothèse(s) validée(s) sur ${validationTotal}. Un contrôle technique ne remplace pas la validation avec Basile.`,status:validationCount===validationTotal?'ok':'warning',link:'/budget/gimi/2027/hypotheses'},
  ];
  const sourceStatus=(value:unknown):BudgetControlStatus=>value?'ok':loading?'warning':'missing';
  const sources:Array<{data:string;origin:string;period:string;transformation:string;status:BudgetControlStatus}>=[
    {data:'Base du compte de résultat 2026',origin:projection.source==='interimAnnualized'?'Odoo · écritures validées':'Fichier Budget 2026 · premier onglet',period:projection.source==='interimAnnualized'?`01/01/2026–${new Date(`${projection.baseDate}T12:00:00`).toLocaleDateString('fr-BE')}`:'Budget annuel 2026',transformation:projection.source==='interimAnnualized'?'Annualisation à partir du dernier mois clôturé':'Valeurs de référence provisoires',status:projection.source==='interimAnnualized'?'ok':'warning'},
    {data:'KPI compte de résultat',origin:'Reporting financier Gimi · Odoo',period:'2026 au dernier mois clôturé',transformation:'Extrapolation annuelle existante',status:sourceStatus(profit)},
    {data:'Marge par département',origin:'Analyse de marge · Odoo + clés analytiques',period:'2026 au dernier mois clôturé',transformation:'Ventilation selon la configuration analytique enregistrée',status:sourceStatus(margin)},
    {data:'BFR',origin:'Reporting financier Gimi · onglet BFR',period:'2026 au dernier mois clôturé',transformation:'Ratio BFR / CA ; variation avec signe trésorerie opposé',status:sourceStatus(bfr)},
    {data:'Saisonnalité CA et marge',origin:'Comptes de résultat mensuels Odoo 2025 et 2026',period:'2025 complet + mois clôturés 2026',transformation:'Profil 2025 affiné par 2026 puis normalisé sur le total 2027',status:seasonality?'ok':loading?'warning':'missing'},
    {data:'CAPEX',origin:'Reporting Investissements – CAPEX · Odoo',period:'Réalisé 2026 + hypothèses 2027–2036',transformation:'Le réalisé sert de repère ; aucune reconduction automatique',status:sourceStatus(capex)},
    {data:'Dette CBC et MBP',origin:'Fichier Budget 2026 · lignes CF fin rachat 1 et CF MBP group',period:'Échéanciers 2027–2036',transformation:'Capital uniquement ; référence MBP agrégée tant que le split n’est pas confirmé',status:debtComplete?(plan.debtForecast.useMbpGroupReference?'warning':'ok'):'missing'},
    {data:'Trésorerie historique',origin:'Flux de trésorerie Gimi · Odoo',period:cashFlow?.through?`Solde au ${new Date(`${cashFlow.through}T12:00:00`).toLocaleDateString('fr-BE')}`:'Dernier mois clôturé',transformation:'Repère de clôture, jamais assimilé automatiquement au 1er janvier 2027',status:sourceStatus(cashFlow)},
    {data:'Rémunérations futures',origin:'Configuration analytique employés + hypothèses saisies',period:'Coûts 2026, entrées 2027–2036',transformation:'Indexation annuelle puis prorata journalier à la date d’entrée',status:plan.salaryIndexation.cp14901===null?'warning':'ok'},
    {data:'Bâtiment et Bajoma',origin:'Hypothèses manuelles documentées',period:'2027–2036',transformation:'Loyer proratisé à partir de mai 2028 ; Bajoma comptabilisé HTVA',status:plan.validation.building&&plan.validation.bajoma?'ok':'warning'},
    {data:'Flux confidentiel dirigeant',origin:'Barème privé conservé côté API',period:'2027–2036',transformation:'Calcul intégré aux agrégats ; détail jamais envoyé au navigateur',status:'warning'},
  ];
  const allStatuses=[...checks.map(item=>item.status),...sources.map(item=>item.status)],count=(status:BudgetControlStatus)=>allStatuses.filter(item=>item===status).length;
  return <>
    <Card className="control-hero"><ShieldCheck/><div><p className="eyebrow">Traçabilité et qualité</p><h2>Contrôles du budget et origine des données</h2><p>Cette page vérifie la cohérence technique et la complétude. Elle ne certifie pas qu’une hypothèse économique est correcte : les points jaunes doivent encore être confirmés avec Basile.</p></div><div className="control-score"><strong>{count('ok')}</strong><span>contrôles réussis</span></div></Card>
    <div className="control-kpis"><div className="control-kpi ok"><CheckCircle2/><span><strong>{count('ok')}</strong>Contrôles réussis</span></div><div className="control-kpi warning"><FileCheck2/><span><strong>{count('warning')}</strong>À confirmer</span></div><div className="control-kpi missing"><Database/><span><strong>{count('missing')}</strong>Indisponibles</span></div><div className="control-kpi neutral"><Activity/><span><strong>Rév. {plan.revision}</strong>Version enregistrée</span></div></div>
    <Card className="control-list-card"><div className="card-title-row"><div><p className="eyebrow">Checklist automatique</p><h2>Cohérence et complétude</h2></div><span>{checks.filter(item=>item.status==='ok').length} / {checks.length} réussis</span></div><div className="control-list">{checks.map(item=><div className={`control-item ${item.status}`} key={item.title}><span className="control-status-dot"/><div><strong>{item.title}</strong><p>{item.detail}</p></div><span className="control-status-label">{controlStatusLabel[item.status]}</span>{item.link&&<NavLink to={item.link}>Voir</NavLink>}</div>)}</div></Card>
    <Card className="source-register-card"><div className="card-title-row"><div><p className="eyebrow">Registre de provenance</p><h2>D’où viennent les chiffres</h2><p>Source, période et transformation appliquée pour chaque famille de données.</p></div></div><div className="budget-table-wrap"><table className="source-register-table"><thead><tr><th>Donnée</th><th>Source</th><th>Période</th><th>Traitement dans le budget</th><th>État</th></tr></thead><tbody>{sources.map(row=><tr key={row.data}><th>{row.data}</th><td>{row.origin}</td><td>{row.period}</td><td>{row.transformation}</td><td><span className={`source-status ${row.status}`}>{controlStatusLabel[row.status]}</span></td></tr>)}</tbody></table></div></Card>
    <Card className="control-method-card"><Database/><div><h3>Règle de prudence</h3><p>Une source absente reste « indisponible ». Elle n’est jamais transformée en zéro. Une cohérence arithmétique réussie signifie que les formules se réconcilient, pas que les hypothèses de croissance, de marge, de BFR ou d’investissement ont été validées.</p></div></Card>
  </>;
}

const monthName=(month:string)=>new Date(`${month}-15T12:00:00`).toLocaleDateString('fr-BE',{month:'long'});

function Assumptions({plan,editable,onChange}:{plan:GimiBudgetPlan;editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  const updateScenario=(scenario:GimiBudgetScenarioName,driver:GimiBudgetDriver,year:GimiBudgetYear,value:number|null)=>onChange({...plan,scenarios:{...plan.scenarios,[scenario]:{...plan.scenarios[scenario],values:{...plan.scenarios[scenario].values,[driver]:{...plan.scenarios[scenario].values[driver],[year]:value}}}}});
  return <>
    <Card className="budget-basis-card"><div><p className="eyebrow">Point de départ</p><h2>Situation intermédiaire</h2><p>Les projections partent de la situation comptable arrêtée au 31 octobre 2026. Cette base devra être rapprochée du réalisé définitif avant validation du budget.</p></div><label className="budget-switch"><input type="checkbox" checked={plan.useInterimBase} disabled={!editable} onChange={event=>onChange({...plan,useInterimBase:event.target.checked})}/><span>Utiliser la situation au</span><Input type="date" value={plan.baseDate} disabled={!editable||!plan.useInterimBase} onChange={event=>onChange({...plan,baseDate:event.target.value})}/></label></Card>
    <Card className="budget-validation"><div><p className="eyebrow">Réunion Basile</p><h2>Hypothèses à confirmer</h2><p>Une case cochée signifie que l’hypothèse a été revue ensemble, pas qu’elle provient d’un réalisé comptable.</p></div><div className="validation-grid">{Object.entries(validationLabels).map(([key,label])=><label key={key}><input type="checkbox" checked={plan.validation[key as keyof GimiBudgetPlan['validation']]} disabled={!editable} onChange={event=>onChange({...plan,validation:{...plan.validation,[key]:event.target.checked}})}/><CheckCircle2 size={17}/><span>{label}</span></label>)}</div></Card>
    <div className="scenario-selector">{(['best','neutral','worst'] as const).map(name=><button type="button" className={plan.selectedScenario===name?'active':''} key={name} onClick={()=>editable&&onChange({...plan,selectedScenario:name})}><strong>{scenarioLabels[name]}</strong><span>Croissance {percent(plan.scenarios[name].values.growth[2027])}</span></button>)}</div>
    {(['best','neutral','worst'] as const).map(name=><Card className={`scenario-card scenario-${name}${plan.selectedScenario===name?' selected':''}`} key={name}><div className="scenario-heading"><div><p className="eyebrow">Scénario 2027–2036</p><h2>{scenarioLabels[name]}</h2></div>{plan.selectedScenario===name&&<span>Scénario de travail</span>}</div><div className="budget-table-wrap"><table className="budget-matrix"><thead><tr><th>Hypothèse</th><th>Base 2026</th>{gimiBudgetYears.map(year=><th key={year}>{year}</th>)}</tr></thead><tbody>{(Object.keys(driverLabels) as GimiBudgetDriver[]).map(driver=><tr key={driver}><th>{driverLabels[driver]}</th><td>{percent(plan.baseline2026[driver])}</td>{gimiBudgetYears.map(year=><td key={year}><RateInput value={plan.scenarios[name].values[driver][year]} disabled={!editable} onChange={value=>updateScenario(name,driver,year,value)}/></td>)}</tr>)}</tbody></table></div></Card>)}
  </>;
}

function RateInput({value,disabled,onChange}:{value:number|null;disabled:boolean;onChange:(value:number|null)=>void}){return <label className="rate-input"><input type="number" step="0.1" value={value===null?'':Number((value*100).toFixed(4))} placeholder="—" disabled={disabled} onChange={event=>onChange(event.target.value===''?null:Number(event.target.value)/100)}/><span>%</span></label>}

function Remuneration({plan,employees,editable,onChange}:{plan:GimiBudgetPlan;employees:EmployeeAnalyticAllocation[];editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  const functions=useMemo(()=>{
    const grouped=new Map<string,number[]>();for(const employee of employees)if(employee.function&&employee.annualSalaryCost!==null)(grouped.get(employee.function)??(grouped.set(employee.function,[]),grouped.get(employee.function)!)).push(employee.annualSalaryCost);
    return [...grouped.entries()].map(([name,values])=>({name,salary:values.reduce((sum,value)=>sum+value,0)/values.length})).sort((a,b)=>a.name.localeCompare(b.name,'fr-BE'));
  },[employees]);
  const updateHire=(id:string,patch:Partial<GimiBudgetHiring>)=>onChange({...plan,hires:plan.hires.map(hire=>hire.id===id?{...hire,...patch}:hire)});
  const add=()=>onChange({...plan,hires:[...plan.hires,{id:crypto.randomUUID(),count:1,function:'',department:'shared',jointCommittee:'cp200',startDate:'2027-01-01',annualSalary2026:0}]});
  const total=(year:GimiBudgetYear)=>plan.hires.reduce((sum,hire)=>sum+hiringAnnualCost(hire,year,plan.salaryIndexation),0);
  return <>
    <Card className="budget-intro"><UsersRound/><div><p className="eyebrow">Plan d’effectifs</p><h2>Rémunérations et engagements futurs</h2><p>Le coût annuel 2026 peut reprendre la moyenne des personnes exerçant déjà la même fonction. L’impact budgétaire est indexé et proratisé au jour de l’entrée.</p></div></Card>
    <Card className="indexation-card"><div><h3>Indexations salariales</h3><p>Hypothèses annuelles appliquées à partir de 2027.</p></div><label>Employés · CP 200<RateInput value={plan.salaryIndexation.cp200} disabled={!editable} onChange={value=>onChange({...plan,salaryIndexation:{...plan.salaryIndexation,cp200:value}})}/></label><label>Ouvriers · CP 149.01<RateInput value={plan.salaryIndexation.cp14901} disabled={!editable} onChange={value=>onChange({...plan,salaryIndexation:{...plan.salaryIndexation,cp14901:value}})}/><small>{plan.salaryIndexation.cp14901===null?'À confirmer avec Basile':'Hypothèse enregistrée'}</small></label></Card>
    <Card className="hiring-card"><div className="card-title-row"><div><p className="eyebrow">Nouveaux engagements</p><h2>Hypothèses de recrutement</h2></div>{editable&&<Button variant="secondary" onClick={add}><Plus size={16}/>Ajouter</Button>}</div><datalist id="budget-functions">{functions.map(item=><option key={item.name} value={item.name}/>)}</datalist><div className="budget-table-wrap"><table className="hiring-table"><thead><tr><th>Nombre</th><th>Fonction</th><th>Département</th><th>CP</th><th>Date d’entrée</th><th>Coût annuel 2026</th><th>Impact 2027</th><th></th></tr></thead><tbody>{plan.hires.map(hire=>{const suggested=functions.find(item=>item.name===hire.function)?.salary;return <tr key={hire.id}><td><Input type="number" min="1" step="1" value={hire.count} disabled={!editable} onChange={event=>updateHire(hire.id,{count:Math.max(1,Number(event.target.value)||1)})}/></td><td><Input list="budget-functions" value={hire.function} disabled={!editable} onChange={event=>{const name=event.target.value,next=functions.find(item=>item.name===name)?.salary;updateHire(hire.id,{function:name,...(hire.annualSalary2026===0&&next?{annualSalary2026:Math.round(next)}:{})})}}/>{suggested&&<small>Moyenne actuelle : {money.format(suggested)}</small>}</td><td><Select value={hire.department} disabled={!editable} onChange={event=>updateHire(hire.id,{department:event.target.value as GimiBudgetHiring['department']})}>{Object.entries(departments).map(([value,label])=><option key={value} value={value}>{label}</option>)}</Select></td><td><Select value={hire.jointCommittee} disabled={!editable} onChange={event=>updateHire(hire.id,{jointCommittee:event.target.value as GimiBudgetHiring['jointCommittee']})}><option value="cp200">CP 200</option><option value="cp14901">CP 149.01</option></Select></td><td><Input type="date" value={hire.startDate} disabled={!editable} onChange={event=>updateHire(hire.id,{startDate:event.target.value})}/></td><td><Input type="number" min="0" step="100" value={hire.annualSalary2026} disabled={!editable} onChange={event=>updateHire(hire.id,{annualSalary2026:Math.max(0,Number(event.target.value)||0)})}/></td><td><strong>{money.format(hiringAnnualCost(hire,2027,plan.salaryIndexation))}</strong></td><td>{editable&&<button className="icon-button" aria-label={`Supprimer ${hire.function||'le recrutement'}`} onClick={()=>onChange({...plan,hires:plan.hires.filter(item=>item.id!==hire.id)})}><Trash2 size={17}/></button>}</td></tr>})}{!plan.hires.length&&<tr><td colSpan={8} className="empty-row">Aucun recrutement ajouté.</td></tr>}</tbody></table></div></Card>
    <Card className="ten-year-summary"><h2>Impact annuel des recrutements</h2><div className="year-kpis">{gimiBudgetYears.map(year=><div key={year}><span>{year}</span><strong>{money.format(total(year))}</strong></div>)}</div></Card>
  </>;
}

function BuildingAndManagement({plan,editable,onChange}:{plan:GimiBudgetPlan;editable:boolean;onChange:(value:GimiBudgetPlan)=>void}){
  const vatMonthly=plan.bajoma.monthlyExclVat*(1+plan.bajoma.vatRate);
  return <>
    <div className="budget-two-columns"><Card><div className="card-title-row"><div><p className="eyebrow">Immobilier</p><h2>Nouveau bâtiment</h2></div><Building2/></div><div className="assumption-form"><label>Loyer annuel actuel<Input type="number" min="0" step="1000" value={plan.building.currentAnnualRent} disabled={!editable} onChange={event=>onChange({...plan,building:{...plan.building,currentAnnualRent:Number(event.target.value)||0}})}/></label><label>Début du nouveau loyer<Input type="date" value={plan.building.startDate} disabled={!editable} onChange={event=>onChange({...plan,building:{...plan.building,startDate:event.target.value}})}/></label><label>Nouveau loyer annuel<Input type="number" min="0" step="1000" value={plan.building.annualRent} disabled={!editable} onChange={event=>onChange({...plan,building:{...plan.building,annualRent:Number(event.target.value)||0}})}/></label><label>Indexation annuelle<RateInput value={plan.building.annualIndexation} disabled={!editable} onChange={value=>onChange({...plan,building:{...plan.building,annualIndexation:value??0}})}/></label></div><p className="report-note">En 2028, le loyer actuel couvre janvier à avril et le nouveau loyer couvre mai à décembre. L’indexation intervient ensuite à chaque anniversaire du bail.</p></Card>
    <Card><p className="eyebrow">Flux intragroupe</p><h2>Refacturation Bajoma → Gimi</h2><div className="assumption-form"><label>Date de début<Input type="date" value={plan.bajoma.startDate} disabled={!editable} onChange={event=>onChange({...plan,bajoma:{...plan.bajoma,startDate:event.target.value}})}/></label><label>Montant mensuel HTVA<Input type="number" min="0" step="0.01" value={plan.bajoma.monthlyExclVat} disabled={!editable} onChange={event=>onChange({...plan,bajoma:{...plan.bajoma,monthlyExclVat:Number(event.target.value)||0}})}/></label><label>TVA<RateInput value={plan.bajoma.vatRate} disabled={!editable} onChange={value=>onChange({...plan,bajoma:{...plan.bajoma,vatRate:value??0}})}/></label></div><div className="bajoma-summary"><span>Mensuel HTVA<strong>{preciseMoney.format(plan.bajoma.monthlyExclVat)}</strong></span><span>Mensuel TVAC<strong>{preciseMoney.format(vatMonthly)}</strong></span></div><p className="report-note">Seul le montant HTVA affecte le compte de résultat budgété ; la TVA est présentée pour le flux de facturation.</p></Card></div>
    <Card className="ten-year-summary"><h2>Synthèse des engagements spécifiques</h2><div className="budget-table-wrap"><table className="budget-matrix"><thead><tr><th>Hypothèse</th>{gimiBudgetYears.map(year=><th key={year}>{year}</th>)}</tr></thead><tbody><tr><th>Loyer Gimi</th>{gimiBudgetYears.map(year=><td key={year}>{money.format(buildingAnnualRent(plan.building,year))}</td>)}</tr><tr><th>Bajoma · HTVA</th>{gimiBudgetYears.map(year=><td key={year}>{money.format(bajomaAnnualCharge(plan.bajoma,year))}</td>)}</tr></tbody></table></div></Card>
  </>;
}
